import {optimizedLayout,curve,curvePath} from './layout.js?v=3';
const $ = s => document.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = u => {try {const x = new URL(u);return ['https:','http:'].includes(x.protocol) ? esc(x.href) : '#';} catch {return '#';}};
const names = new Proxy({}, {get: (_, key) => String(key).replaceAll('--', '–')});
const categoryColors=['#247c70','#aa6540','#6a70a8','#a95373','#9a7d24','#4d7f9f','#8b674a','#637d36','#a75c53','#568c85','#7c6094','#79854d'];
let data, group, selected = null, page = 0, overview = false, activeEdges = [], activePapers = [], depthReference = null, hiddenLongEdges = 0;
const filters = () => ({dataset:$('#dataset').value, metric:$('#metric').value, year:$('#year').value, search:$('#search').value.toLowerCase(), shared:$('#shared').checked, maxSpan:Number($('#depth-limit').value), positive:$('#positive').checked});
const recordSort = (a,b) => Number(b.metric==='NDCG@10')-Number(a.metric==='NDCG@10') || Number(b.dataset==='Beauty')-Number(a.dataset==='Beauty') || [a.dataset,a.metric,a.protocol,a.id].join('|').localeCompare([b.dataset,b.metric,b.protocol,b.id].join('|'));
function edgeMagnitude(records){const sorted=[...records].sort(recordSort);const record=sorted.find(r=>r.improvement!==null&&Number.isFinite(r.improvement));const magnitude=record?Math.abs(record.improvement):null;return {record,magnitude,width:magnitude===null?1:magnitude<.1?1.2:magnitude<.2?1.2:magnitude<.3?2:3,color:magnitude===null?'#8b9585':magnitude<.1?'#83957b':magnitude<.2?'#b2bbae':'#566a50',dash:magnitude===null?'0.1 3':magnitude<.1?'0.1 2.8':''};}
function treeLayout(papers,edges){
  const ids=new Set(papers.map(p=>p.id)), adjacency=new Map(papers.map(p=>[p.id,[]]));
  for(const e of edges)if(ids.has(e.source)&&ids.has(e.target))adjacency.get(e.source).push(e.target);
  // Condense strongly connected components before ranking; retain every original edge.
  let serial=0;const indices=new Map(),low=new Map(),stack=[],onStack=new Set(),components=[],componentOf=new Map();
  function visit(id){indices.set(id,serial);low.set(id,serial++);stack.push(id);onStack.add(id);for(const next of adjacency.get(id)){if(!indices.has(next)){visit(next);low.set(id,Math.min(low.get(id),low.get(next)));}else if(onStack.has(next))low.set(id,Math.min(low.get(id),indices.get(next)));}if(low.get(id)===indices.get(id)){const members=[];let n;do{n=stack.pop();onStack.delete(n);componentOf.set(n,components.length);members.push(n);}while(n!==id);components.push(members);}}
  papers.forEach(p=>{if(!indices.has(p.id))visit(p.id);});
  const outgoing=components.map(()=>new Set()),incoming=components.map(()=>0),rank=components.map(()=>0);
  for(const e of edges){const a=componentOf.get(e.source),b=componentOf.get(e.target);if(a!==undefined&&b!==undefined&&a!==b&&!outgoing[a].has(b)){outgoing[a].add(b);incoming[b]++;}}
  const queue=incoming.flatMap((n,i)=>n===0?[i]:[]);for(let i=0;i<queue.length;i++){const a=queue[i];for(const b of outgoing[a]){rank[b]=Math.max(rank[b],rank[a]+1);if(--incoming[b]===0)queue.push(b);}}
  const layers=[];papers.forEach(p=>{const r=rank[componentOf.get(p.id)];(layers[r]??=[]).push(p);});
  layers.forEach(l=>l.sort((a,b)=>Number(b.baselineOnly)-Number(a.baselineOnly)||(a.year??9999)-(b.year??9999)||b.citations-a.citations||a.label.localeCompare(b.label)));
  // Barycentric ordering reduces crossings without removing multi-parent links.
  for(let pass=0;pass<4;pass++)for(let r=1;r<layers.length;r++){const positions=new Map(layers.flatMap(l=>l.map((p,i)=>[p.id,i])));const center=p=>{const parents=edges.filter(e=>e.target===p.id&&rank[componentOf.get(e.source)]<r).map(e=>positions.get(e.source));return parents.length?parents.reduce((a,b)=>a+b,0)/parents.length:positions.get(p.id);};layers[r].sort((a,b)=>center(a)-center(b)||a.id.localeCompare(b.id));}
  const width=Math.max(940,layers.length*250+80),height=Math.max(600,...layers.map(l=>l.length*38+150));const points=new Map();layers.forEach((l,r)=>l.forEach((p,i)=>points.set(p.id,{p,rank:r,x:70+r*(width-300)/Math.max(1,layers.length-1),y:100+i*38+(height-150-l.length*38)/2})));return {points,width,height,layers,componentOf};
}
function surveyPapers(g){return data.papers.filter(p=>g==='all'?!p.external:p.applications.includes(g));}
function groupEdges(g){const ids=new Set(surveyPapers(g).map(p=>p.id));return data.edges.filter(e=>ids.has(e.target));}
function groupPapers(g){const ids=new Set(surveyPapers(g).map(p=>p.id));const edges=groupEdges(g);const uses=new Map();for(const e of edges){if(!uses.has(e.source))uses.set(e.source,new Set());uses.get(e.source).add(e.target);}for(const e of edges)ids.add(e.source);return data.papers.filter(p=>ids.has(p.id)).map(p=>({...p,baselineOnly:g==='all'?!!p.external:!p.applications.includes(g),shared:(uses.get(p.id)?.size||0)>=2,baselineUses:uses.get(p.id)?.size||0}));}
function nav(){ $('#groups').innerHTML=`<button class="group ${group==='all'?'active':''}" data-group="all"><span class="number">◎</span><span>Global overview<small>All papers · all applications</small></span></button><div class="nav-label">APPLICATIONS / 12</div>`+data.applications.map((g,i)=>`<button class="group ${g===group&&!overview?'active':''}" data-group="${esc(g)}"><span class="number">${String(i+1).padStart(2,'0')}</span><span>${names[g]}<small>${surveyPapers(g).length} papers + ${groupPapers(g).filter(p=>p.baselineOnly).length} baselines · ${groupEdges(g).length} comparisons</small></span></button>`).join('');$('#groups').querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>setGroup(b.dataset.group));}
function setGroup(g){group=g;if(g==='all'){$('#layout-mode').value='tree';$('#positive').checked=false;$('#shared').checked=true;}selected=null;overview=false;page=0;$('#search').value='';['dataset','metric','year'].forEach(id=>$('#'+id).value='');nav();options();render();}
function options(){const records=groupEdges(group).flatMap(e=>e.records);for(const [id,values,label] of [['dataset',records.map(r=>r.dataset),'All datasets'],['metric',records.map(r=>r.metric),'All metrics'],['year',surveyPapers(group).map(p=>p.year),'All years']]){$('#'+id).innerHTML=`<option value="">${label}</option>`+[...new Set(values)].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true})).map(v=>`<option>${esc(v)}</option>`).join('');}}
function getVisible(){const f=filters();const targets=new Set(surveyPapers(group).filter(p=>!f.year||String(p.year)===f.year).map(p=>p.id));let edges=groupEdges(group).filter(e=>targets.has(e.target)).map(e=>({...e,filtered:e.records.filter(r=>(!f.dataset||r.dataset===f.dataset)&&(!f.metric||r.metric===f.metric))})).filter(e=>e.filtered.length&&(!f.positive||e.filtered.some(r=>r.improvement>0)));const all=groupPapers(group);const uses=new Map();for(const e of edges){if(!uses.has(e.source))uses.set(e.source,new Set());uses.get(e.source).add(e.target);}if(!f.shared){const shared=new Set(all.filter(p=>p.baselineOnly).map(p=>p.id));edges=edges.filter(e=>!shared.has(e.source));}const ids=new Set(targets);edges.forEach(e=>{ids.add(e.source);ids.add(e.target);});const papers=all.filter(p=>ids.has(p.id)).map(p=>({...p,baselineUses:uses.get(p.id)?.size||0,shared:(uses.get(p.id)?.size||0)>=2}));depthReference=treeLayout(papers,edges);const before=edges.length;edges=edges.filter(e=>Math.abs(depthReference.points.get(e.source).rank-depthReference.points.get(e.target).rank)<f.maxSpan);hiddenLongEdges=before-edges.length;const connected=new Set(edges.flatMap(e=>[e.source,e.target]));const visiblePapers=papers.filter(p=>connected.has(p.id));depthReference.points=new Map([...depthReference.points].filter(([id])=>connected.has(id)));depthReference.layers=depthReference.layers.map(l=>l.filter(p=>connected.has(p.id)));const visibleUses=new Map();for(const e of edges){if(!visibleUses.has(e.source))visibleUses.set(e.source,new Set());visibleUses.get(e.source).add(e.target);}return {papers:visiblePapers.map(p=>({...p,baselineUses:visibleUses.get(p.id)?.size||0,shared:(visibleUses.get(p.id)?.size||0)>=2})),edges};}

function currentLayout(papers,edges,mode=$('#layout-mode')?.value||'tree'){return optimizedLayout(!overview&&depthReference?depthReference:treeLayout(papers,edges),edges,mode);}
function graph(papers,edges,mini=false,key='main'){
  const {points:pts,width,height,layers,mode}=currentLayout(papers,edges);
  let defs='';
  let curves='';edges.forEach((e,i)=>{const a=pts.get(e.source),b=pts.get(e.target);if(!a||!b)return;const magnitude=edgeMagnitude(e.filtered||e.records);const id=`arrow-${key}-${i}`;defs+=`<marker id="${id}" viewBox="0 0 10 10" refX="9" refY="5" markerUnits="userSpaceOnUse" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="${magnitude.color}"/></marker>`;
    const path=curvePath(curve(a,b,mode));
    curves+=`<path class="edge" data-edge="${i}" d="${path}" stroke="${magnitude.color}" style="stroke-width:${magnitude.width}px;stroke-linecap:round" ${magnitude.dash?`stroke-dasharray="${magnitude.dash}"`:String()} marker-end="url(#${id})"/>${mini?'':`<path class="edge-hit" data-edge="${i}" d="${path}" tabindex="0" role="button" aria-label="${esc(a.p.label)} to ${esc(b.p.label)}, ${e.filtered.length} experiments"><title>${esc(a.p.label)} → ${esc(b.p.label)} · ${magnitude.magnitude===null?'change unavailable':(magnitude.magnitude*100).toFixed(2)+'% absolute change'}</title></path>`}`;
  });
  const columns=mode==='radial'?layers.map((l,r)=>{const n=l.map(p=>pts.get(p.id)).find(p=>p.radius);if(!n)return '';const cx=n.x-Math.cos(n.angle)*n.radius,cy=n.y-Math.sin(n.angle)*n.radius;const baseline=l.every(p=>p.baselineOnly);return `<circle cx="${cx}" cy="${cy}" r="${n.radius}" fill="none" stroke="${baseline?'#b28242':'#d5ddd0'}" stroke-dasharray="2 7"/><text x="${cx}" y="${cy-n.radius-18}" text-anchor="middle" class="axis-label">${baseline?'BASELINE CONTEXT / OUTER RING':'VQ METHODS / LAYER '+r}</text>`;}).join(''):layers.map((l,r)=>{const n=l.map(p=>pts.get(p.id)).find(p=>p&&edges.some(e=>e.source===p.p.id||e.target===p.p.id));if(!n)return '';return `<line x1="${n.x}" y1="64" x2="${n.x}" y2="${height-30}" stroke="#e0e4d8" stroke-dasharray="2 7"/><text x="${n.x}" y="38" class="axis-label">${r===0?'ROOTS / BASELINES':'COMPARISON DEPTH '+r}</text>`;}).join('');
  const nodes=[...pts.values()].map(({p,x,y})=>{const label=p.label.length>27?p.label.slice(0,26)+'…':p.label;const colors=p.applications.map(a=>categoryColors[data.applications.indexOf(a)]).filter(Boolean);const radius=7;const ringRadius=radius+3,circumference=2*Math.PI*ringRadius;const rings=group==='all'?colors.map((color,i)=>`<circle class="category-ring" cx="${x}" cy="${y}" r="${ringRadius}" fill="none" style="stroke:${color};stroke-width:2.5px" stroke-dasharray="${circumference/colors.length} ${circumference-circumference/colors.length}" transform="rotate(${i*360/colors.length-90} ${x} ${y})"/>`).join(''):'';return `<g class="node ${p.shared?'shared':''} ${p.baselineOnly?'baseline-node':''}" data-id="${esc(p.id)}" ${mini?'':'tabindex="0" role="button"'} aria-label="${esc(p.label)}, ${p.year??'year unknown'}"><circle cx="${x}" cy="${y}" r="${radius}" fill="${group==='all'?(colors[0]||'#9b9c91'):p.baselineOnly?'#f4f3ed':'#338666'}" style="${group==='all'?'stroke:#fafaf5;stroke-width:1':p.baselineOnly?'stroke:#b28242;stroke-width:2':''}"/>${rings}<rect x="${x+15}" y="${y-12}" width="${Math.min(192,label.length*6.2+7)}" height="24" fill="#fafaf5" opacity=".94"/><text x="${x+20}" y="${y+4}">${esc(label)}</text><title>${esc(p.title)} (${p.year??'year unknown'}) · ${esc(p.applications.join('; ')||'External baseline')} · ${p.baselineUses||0} compared papers</title></g>`;}).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${mini?940:width}" height="${mini?840:height}" class="tree-canvas"><defs>${defs}</defs>${columns}${curves}${nodes}</svg>`;
}

function render(){const {papers,edges}=getVisible();activeEdges=edges;activePapers=papers;$('#group-index').textContent=group==='all'?'GLOBAL OVERVIEW / ALL APPLICATIONS':`APPLICATION ${String(data.applications.indexOf(group)+1).padStart(2,'0')} / 12`;$('#category-legend').innerHTML=(group==='all'?'<b>APPLICATION COLORS</b>'+data.applications.map((a,i)=>`<span><i style="background:${categoryColors[i]}"></i>${esc(names[a])}</span>`).join('')+'<span><i style="background:#9b9c91"></i>External baseline</span><small>Segmented rings indicate multiple applications. Colors identify applications; edge width identifies relative change.</small>':'');$('#category-legend').hidden=group!=='all';$('#group-title').textContent=group==='all'?'The complete method landscape':overview?'Applications at a glance':names[group];$('#group-subtitle').textContent=group==='all'?'All 179 survey papers and resolved external baselines in one graph.':overview?'One evidence map per application. Select a group to explore.':group;$('.graph-area').hidden=overview;$('.filters').hidden=overview;$('#overview-grid').hidden=!overview;
  if(overview){$('#overview-grid').innerHTML=data.applications.map((g,i)=>{const ps=groupPapers(g),es=groupEdges(g);return `<button class="mini" data-group="${esc(g)}"><h3>${String(i+1).padStart(2,'0')} / ${names[g]}</h3><p>${ps.length} papers · ${es.length} comparisons</p><svg viewBox="0 0 940 840" aria-label="${esc(names[g])}">${graph(ps,es,true,'mini'+i)}</svg></button>`;}).join('');$('#overview-grid').querySelectorAll('button').forEach(b=>b.onclick=()=>setGroup(b.dataset.group));defaultDetail();return;}
  $('#counts').textContent=`${papers.length} nodes / ${edges.length} comparisons / ${edges.reduce((n,e)=>n+e.filtered.length,0)} experiments${hiddenLongEdges?` / ${hiddenLongEdges} long-range links hidden`:String()}`;const dimensions=currentLayout(papers,edges);const alternate=currentLayout(papers,edges,dimensions.mode==='tree'?'radial':'tree');const m=dimensions.metrics;$('#layout-stats').innerHTML=`<span><b>${Math.round(m.total).toLocaleString()}</b> total length</span><span><b>${m.saved.toFixed(1)}%</b> shorter than initial</span><span><b>${m.crossings}</b> crossing pairs</span><span><b>${Math.round(m.average)}</b> mean / <b>${Math.round(m.max)}</b> max</span><span><b>${(m.area/1e6).toFixed(2)} M</b> area</span><small>SVG units · 18-segment curve estimates · fixed 11px labels and 218 × 32px clearance. ${alternate.mode==='tree'?'Layered':'Concentric'}: ${Math.round(alternate.metrics.total).toLocaleString()} total, ${alternate.metrics.crossings} crossing pairs. Local optimum; global minimum is not guaranteed.</small>`;$('#graph').setAttribute('viewBox',`0 0 ${dimensions.width} ${dimensions.height}`);$('#graph').dataset.fit='false';$('#graph').style.width=dimensions.width+'px';$('#graph').style.height=dimensions.height+'px';$('#graph').innerHTML=graph(papers,edges);$('#empty').hidden=!!edges.length;$('#graph').querySelectorAll('.node').forEach(n=>{n.onclick=()=>{selected={type:'paper',id:n.dataset.id};page=0;detail();highlight();};n.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();n.onclick();}};});$('#graph').querySelectorAll('.edge-hit').forEach(n=>{n.onclick=()=>{selected={type:'edge',source:edges[+n.dataset.edge].source,target:edges[+n.dataset.edge].target};page=0;detail();highlight();};n.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();n.onclick();}};n.onmouseenter=()=>hoverEdge(+n.dataset.edge);n.onmouseleave=highlight;});detail();highlight();
}
function hoverEdge(i){$('#graph').querySelectorAll('.edge').forEach(e=>e.classList.toggle('dim',+e.dataset.edge!==i));}
function highlight(){const q=filters().search;const matches=new Set(activePapers.filter(p=>(p.label+' '+p.title).toLowerCase().includes(q)).map(p=>p.id));let connected=null;if(selected?.type==='paper'){connected=new Set([selected.id]);activeEdges.forEach(e=>{if(e.source===selected.id||e.target===selected.id){connected.add(e.source);connected.add(e.target);}});}$('#graph').querySelectorAll('.node').forEach(n=>{n.classList.toggle('dim',(!matches.has(n.dataset.id))||(connected&&!connected.has(n.dataset.id)));n.classList.toggle('selected',selected?.id===n.dataset.id);});$('#graph').querySelectorAll('.edge').forEach(n=>{const e=activeEdges[+n.dataset.edge];const picked=selected?.type==='edge'&&e.source===selected.source&&e.target===selected.target;n.classList.toggle('selected',picked);n.classList.toggle('dim',(q&&!matches.has(e.source)&&!matches.has(e.target))||(selected?.type==='paper'&&e.source!==selected.id&&e.target!==selected.id)||(selected?.type==='edge'&&!picked));});}
function defaultDetail(){$('#details').innerHTML=`<div class="aside-label">EXPLORE THE CONNECTIONS</div><h3 class="detail-title">Follow the comparison.<br>Read the evidence.</h3><p class="detail-copy">${overview?'Choose an application to explore its methods and shared baselines.':'Select a paper to trace its connections, or a curve to inspect quantitative evidence.'}</p><div class="big-arrow">↗</div><div class="instruction"><b>Read the line style</b><p>Light dots, light solid, dark solid, and thick dark solid encode increasing absolute relative change. Arrows indicate baseline-to-method direction. Signed changes remain in experiment details.</p></div><div class="instruction"><b>From roots to methods</b><p>All resolved baselines are included, even when compared by only one paper. Select a baseline to trace its branches.</p></div><div class="instruction"><b>Evidence, with its limits</b><p>Edges require experimental records and either an explicit citation relation or a resolved bibliography mapping. Unresolved baseline identities are omitted.</p></div>`;}
function detail(){if(!selected){defaultDetail();return;}if(selected.type==='paper'){const p=activePapers.find(p=>p.id===selected.id)||data.papers.find(p=>p.id===selected.id);const es=activeEdges.filter(e=>e.source===p.id||e.target===p.id);$('#details').innerHTML=`<div class="aside-label">PAPER / ${p.year ?? 'YEAR NOT REPORTED'}</div><h3 class="detail-title">${esc(p.label)}</h3>${p.shared?`<span class="pill">Shared baseline · ${p.baselineUses} papers</span>`:""}${p.external?'<span class="pill">External baseline</span>':''}<p class="detail-copy">${esc(p.title)}</p><span class="pill">${esc(p.venue||'Venue not specified')}</span><span class="pill">Workbook citations ${p.citations}</span><p class="detail-copy">${p.external?'Bibliographic identity resolved from the workbook baseline audit.':'Survey paper indexed under: '+esc(p.applications.join('; '))}</p><a class="detail-link" href="${safeUrl(p.url)}" target="_blank" rel="noopener">Read paper ↗</a><div class="instruction"><b>${es.length} visible comparisons</b></div>${es.map((e,i)=>`<button class="neighbor" data-neighbor="${i}">${esc(data.papers.find(p=>p.id===e.source).label)} → ${esc(data.papers.find(p=>p.id===e.target).label)}<br><small>${e.filtered.length} experiments ↗</small></button>`).join('')}`;$('#details').querySelectorAll('[data-neighbor]').forEach(b=>b.onclick=()=>{const e=es[+b.dataset.neighbor];selected={type:'edge',source:e.source,target:e.target};page=0;detail();highlight();});return;}
  const e=activeEdges.find(e=>e.source===selected.source&&e.target===selected.target);if(!e){selected=null;defaultDetail();return;}const a=data.papers.find(p=>p.id===e.source),b=data.papers.find(p=>p.id===e.target);const sorted=[...e.filtered].sort(recordSort);const representative=sorted.find(r=>r.improvement!==null);const ordered=representative?[representative,...sorted.filter(r=>r!==representative)]:sorted;page=Math.min(page,ordered.length-1);const r=ordered[page];const fmt=x=>x===null?'Not reported':Number(x).toLocaleString('en-US',{maximumSignificantDigits:7});const pct=r.improvement===null?'Change unavailable':`${r.improvement>0?'+':''}${(r.improvement*100).toFixed(2)}%`;
  $('#details').innerHTML=`<div class="aside-label">COMPARISON / EXPERIMENT EVIDENCE</div><p class="detail-copy">Baseline · ${esc(a.label)}</p><h3 class="detail-title">↗ ${esc(b.label)}</h3><p class="detail-copy">This edge contains ${e.filtered.length} filtered experiments / ${e.records.length} total.${page===0?'The first record follows a fixed representative priority.':''}</p><div class="record-nav"><button id="prev" ${page===0?'disabled':''}>←</button><span>Record ${page+1} / ${ordered.length}</span><button id="next" ${page===ordered.length-1?'disabled':''}>→</button></div><section class="evidence"><h4>${esc(r.dataset)} · ${esc(r.metric)}</h4><div class="change ${r.improvement<0?'negative':''}">${pct}</div><p>Direction-adjusted improvement · ${r.direction==='lower'?'Lower is better':'Higher is better'}</p><table><tr><td>Method value</td><td>${fmt(r.methodValue)}</td></tr><tr><td>Baseline value</td><td>${fmt(r.baselineValue)}</td></tr><tr><td>Unit</td><td>${esc(r.unit||'Not specified')}</td></tr></table><p><b>Evaluated method: </b>${esc(r.method)}</p><p><b>Baseline configuration: </b>${esc(r.baseline)}</p><p><b>Protocol: </b>${/[\u3400-\u9fff]/.test(r.protocol)?'See original-language provenance.':esc(r.protocol||'Not reported')}</p><span class="pill">${esc(r.comparison||'Unclassified')}</span><span class="pill">${esc(r.attribution||'Attribution not specified')}</span><p><b>Attribution notes: </b>${/[\u3400-\u9fff]/.test(r.note)?'See original-language source note below.':esc(r.note||'Not reported')}</p><details><summary>Provenance and original-language notes</summary><p>Original attribution: ${esc(r.note)}</p><p>Original protocol: ${esc(r.protocol)}</p><p>Evidence type: ${esc(e.referenceType==='citation_relation'?'Explicit citation relation':'Bibliography mapping (not independently verified)')}</p><p>Citation evidence: ${esc(e.reference)}</p><p>Experiment locator: ${esc(r.locator)}</p><p>Record ID: ${esc(r.id)}</p><p>Verification: ${esc(r.verification||'Not specified')}</p></details><a class="detail-link" href="${safeUrl(r.url)}" target="_blank" rel="noopener">View source experiment ↗</a></section>`;$('#prev').onclick=()=>{page--;detail();};$('#next').onclick=()=>{page++;detail();};
}
async function init(){try{const response=await fetch('data.json', {cache:'no-store'});if(!response.ok)throw Error('Could not load data');data=await response.json();group='all';$('#layout-mode').value='tree';$('#positive').checked=false;nav();options();render();['dataset','metric','year','positive','shared','depth-limit'].forEach(id=>$('#'+id).onchange=()=>{selected=null;page=0;render();});$('#layout-mode').onchange=()=>{render();};$('#fit').onclick=()=>{const svg=$('#graph');const fit=svg.dataset.fit!=='true';svg.dataset.fit=String(fit);svg.style.width=fit?'100%':svg.getAttribute('viewBox').split(' ')[2]+'px';svg.style.height=fit?'auto':svg.getAttribute('viewBox').split(' ')[3]+'px';};$('#search').oninput=highlight;$('#reset').onclick=()=>{selected=null;$('#search').value='';['dataset','metric','year'].forEach(id=>$('#'+id).value='');$('#positive').checked=group!=='all';$('#shared').checked=true;$('#depth-limit').value='2';render();};$('#overview').onclick=()=>setGroup('all');$('#download').onclick=()=>{const clone=$('#graph').cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelectorAll('.edge-hit').forEach(n=>n.remove());const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.orbit{fill:none;stroke:#d8ddd2}.edge{fill:none;stroke-width:1.8;opacity:.6}.node circle{stroke:#fafaf5;stroke-width:2}.node text{font:10px sans-serif;fill:#223b33}.axis-label{font:10px sans-serif;fill:#6e7b70}.axis-year{font:22px sans-serif;fill:#223b33}.center-label{font:10px sans-serif;fill:#6e7b70}.dim{opacity:.045}';clone.prepend(style);const blob=new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='vqrec-'+group.replaceAll(' ','-')+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}catch(e){$('#details').textContent='Data could not be loaded. Open the site through an HTTP server and reload.';console.error(e);}}
init();
